def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def prepare(root,systemd,manifest=MANIFEST):
    plans=[]
    for name,item in manifest.items():
        raw=base64.b64decode(item['data'],validate=True)
        if digest(raw)!=item['sha256']:raise RuntimeError('Installer content mismatch: '+name)
        if name.endswith('.py'):compile(raw,name,'exec')
        target=(systemd/Path(name).name) if item['systemd'] else (root/name)
        if target.is_symlink():raise RuntimeError('Unexpected symlink: '+name)
        before=target.read_bytes() if target.exists() else None
        if before is not None and digest(before) not in item['previous']+[item['sha256']]:
            raise RuntimeError('Unknown installed version; no files changed: '+name)
        plans.append((target,raw,before,target.stat() if target.exists() else None))
    return plans

def replace(target,raw,uid,gid,mode):
    target.parent.mkdir(parents=True,exist_ok=True)
    fd,temp=tempfile.mkstemp(prefix='.fh6-update-',dir=target.parent)
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(raw);stream.flush();os.fsync(stream.fileno())
            os.fchown(stream.fileno(),uid,gid);os.fchmod(stream.fileno(),mode)
        os.replace(temp,target)
    finally:
        if Path(temp).exists():Path(temp).unlink()

def main():
    if os.geteuid()!=0 or socket.gethostname()!='fh6-collector':raise RuntimeError('Run only inside CT109')
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6');units=Path('/etc/systemd/system');config=Path('/etc/fh6/steam-browser.json')
    with (store/'runner.lock').open('a+b') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        for unit in ['fh6-steam.service','fh6-steam.timer']:
            if subprocess.run(['systemctl','is-active','--quiet',unit]).returncode==0:raise RuntimeError('Existing Steam worker active; nothing changed')
        plans=prepare(root,units)
        owner=pwd.getpwnam('fh6');config_added=not config.exists()
